using PaymentAuthorization.Domain;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>
/// Covers the boundary with the payment provider's REST API: what we send on the wire,
/// and how we interpret every shape of answer the provider can give back.
/// </summary>
public sealed class HttpPaymentGatewayTests
{
    [Fact]
    public async Task Sends_the_reference_amount_and_currency_as_the_request_body()
    {
        var handler = new FakeHttpMessageHandler(HttpStatusCode.OK, """{"status":"approved"}""");
        var gateway = CreateGateway(handler);

        await gateway.AuthorizeAsync("ORD-1", new Money(42.50m, "eur"), CancellationToken.None);

        Assert.NotNull(handler.LastRequest);
        Assert.Equal(HttpMethod.Post, handler.LastRequest!.Method);
        Assert.Equal("/v1/authorizations", handler.LastRequest.RequestUri!.PathAndQuery);

        var payload = JsonSerializer.Deserialize<JsonElement>(handler.LastRequestBody!);
        Assert.Equal("ORD-1", payload.GetProperty("reference").GetString());
        Assert.Equal(42.50m, payload.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", payload.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_response_is_read_back_as_approved()
    {
        var handler = new FakeHttpMessageHandler(HttpStatusCode.OK, """{"status":"approved"}""");
        var gateway = CreateGateway(handler);

        var outcome = await gateway.AuthorizeAsync("ORD-2", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_response_is_read_back_as_declined()
    {
        var handler = new FakeHttpMessageHandler(HttpStatusCode.OK, """{"status":"declined"}""");
        var gateway = CreateGateway(handler);

        var outcome = await gateway.AuthorizeAsync("ORD-3", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unrecognized_status_in_a_successful_response_is_treated_as_declined()
    {
        var handler = new FakeHttpMessageHandler(HttpStatusCode.OK, """{"status":"pending"}""");
        var gateway = CreateGateway(handler);

        var outcome = await gateway.AuthorizeAsync("ORD-4", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_empty_body_on_a_successful_response_is_treated_as_declined()
    {
        var handler = new FakeHttpMessageHandler(HttpStatusCode.OK, "null");
        var gateway = CreateGateway(handler);

        var outcome = await gateway.AuthorizeAsync("ORD-5", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task The_provider_refusing_the_payment_outright_with_402_is_read_back_as_declined()
    {
        var handler = new FakeHttpMessageHandler(HttpStatusCode.PaymentRequired, """{"status":"refused"}""");
        var gateway = CreateGateway(handler);

        var outcome = await gateway.AuthorizeAsync("ORD-6", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unexpected_server_error_from_the_provider_is_surfaced_as_a_failure()
    {
        var handler = new FakeHttpMessageHandler(HttpStatusCode.InternalServerError, "oops");
        var gateway = CreateGateway(handler);

        await Assert.ThrowsAsync<HttpRequestException>(
            () => gateway.AuthorizeAsync("ORD-7", new Money(10m, "EUR"), CancellationToken.None));
    }

    private static Infrastructure.HttpPaymentGateway CreateGateway(FakeHttpMessageHandler handler)
    {
        var client = new HttpClient(handler) { BaseAddress = new Uri("https://provider.example.test") };
        return new Infrastructure.HttpPaymentGateway(client);
    }

    private sealed class FakeHttpMessageHandler(HttpStatusCode statusCode, string responseBody) : HttpMessageHandler
    {
        public HttpRequestMessage? LastRequest { get; private set; }
        public string? LastRequestBody { get; private set; }

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            LastRequest = request;
            LastRequestBody = request.Content is null
                ? null
                : await request.Content.ReadAsStringAsync(cancellationToken);

            return new HttpResponseMessage(statusCode)
            {
                Content = new StringContent(responseBody, Encoding.UTF8, "application/json"),
            };
        }
    }
}
